<nav class="pager" aria-label="Audition page sections"><a class="text-link" href="#sessions">Sessions</a><a class="text-link" href="#assign">Assign</a><a class="text-link" href="#notices">Send notices</a><a class="text-link" href="#bookings">Bookings</a><a class="text-link" href="#callbacks">Callbacks</a></nav>
<p>Arrange auditions and callbacks. Invitations are sent only when you press Send notice; no background worker is required. Scheduling does not change the final recruitment decision or public status.</p>
<section class="panel" id="sessions"><h2>Sessions</h2><a class="text-link" href="<?= e(p_url()) ?>">Create a new session →</a><?php foreach($view['sessions'] as $session):?><p><a class="text-link" href="<?= e(p_url('casting','auditions',['session'=>$session['id']])) ?>"><?= e($session['title']) ?></a> · <?= e($session['state'].' · '.p_time($session['starts_at'],$session['display_zone'])) ?></p><?php endforeach;?></section>
<?php $session=$view['session'];$zone=$session['display_zone']??'Africa/Lagos';?>
<section class="panel"><h2><?= $session?'Session details':'New audition session' ?></h2><form method="post" action="<?= e(p_url()) ?>"><?php p_csrf();p_hidden('action','session_save');p_hidden('session_id',$session['id']??0);?>
<label for="session_title">Session title</label><input id="session_title" name="title" maxlength="150" value="<?= e($session['title']??'') ?>" required>
<label for="session_mode">Format</label><select id="session_mode" name="mode"><option value="physical">Physical</option><option value="virtual"<?= ($session['mode']??'')==='virtual'?' selected':'' ?>>Virtual</option></select>
<label for="session_location">Physical location (required for physical auditions)</label><input id="session_location" name="location" maxlength="500" value="<?= e($session['location']??'') ?>">
<label for="meeting_url">HTTPS meeting link (required for virtual auditions)</label><input id="meeting_url" name="meeting_url" type="url" maxlength="1000" value="<?= e($session['meeting_url']??'') ?>">
<label for="session_zone">Time zone for the entered times</label><select id="session_zone" name="display_zone"><option value="Africa/Lagos">Africa/Lagos — WAT (UTC+1)</option><option value="UTC"<?= $zone==='UTC'?' selected':'' ?>>UTC</option></select><p class="field-help">Times are entered in the selected zone. Changing the zone reinterprets the values you type; verify them before saving.</p>
<label for="session_start">Session starts</label><input id="session_start" name="starts_at" type="datetime-local" value="<?= e(p_form_date($session['starts_at']??null,$zone)) ?>" required>
<label for="session_end">Session ends</label><input id="session_end" name="ends_at" type="datetime-local" value="<?= e(p_form_date($session['ends_at']??null,$zone)) ?>" required>
<label for="resource_key">Panel / room identifier</label><input id="resource_key" name="resource_key" value="<?= e($session['resource_key']??'main-panel') ?>" pattern="[a-z0-9][a-z0-9_-]{0,59}" maxlength="60" required><p class="field-help">Reuse the same identifier for the same panel or room. Overlapping sessions for that resource are blocked.</p>
<label for="public_instructions">Instructions for invited applicants</label><textarea id="public_instructions" name="public_instructions" maxlength="3000" rows="4"><?= e($session['public_instructions']??'') ?></textarea>
<label for="session_private_note">Private staff note</label><textarea id="session_private_note" name="private_note" maxlength="4000" rows="3"><?= e($session['private_note']??'') ?></textarea><p class="field-help">Private notes are never included in invitation pages or emails. Once booked, move applicants to a new session to change public session details.</p><button class="button">Save session</button></form>
<?php if($session&&$session['state']==='active'):?><form method="post" action="<?= e(p_url()) ?>"><?php p_csrf();p_hidden('action','session_cancel');p_hidden('session_id',$session['id']);?><p class="field-help">Cancelling revokes all affected invitation links and queues cancellation notices. Send those notices from the queue below.</p><button class="sign-out">Cancel this session and its bookings</button></form><?php endif;?></section>
<?php if($session&&$session['state']==='active'):?>
<section class="panel"><h2>Time slots — <?= e($zone) ?></h2><p><?= e(p_time($session['starts_at'],$zone).' to '.p_time($session['ends_at'],$zone)) ?></p>
<?php foreach($view['slots'] as $slot):?><p><?= e(p_time($slot['starts_at'],$zone).'–'.p_time($slot['ends_at'],$zone)) ?> · <?= e($slot['full_name']??'Available') ?><?= $slot['state']?' · '.e($slot['state']):'' ?></p><?php endforeach;?>
<form method="post" action="<?= e(p_url()) ?>"><?php p_csrf();p_hidden('action','slot_add');p_hidden('session_id',$session['id']);?><label for="slot_start">New slot starts (<?= e($zone) ?>)</label><input id="slot_start" name="starts_at" type="datetime-local" required><label for="slot_end">New slot ends (<?= e($zone) ?>)</label><input id="slot_end" name="ends_at" type="datetime-local" required><button class="button">Add one slot</button></form>
<form method="post" action="<?= e(p_url()) ?>"><?php p_csrf();p_hidden('action','slots_generate');p_hidden('session_id',$session['id']);?><label for="slot_duration">Generate slots: duration in minutes</label><input id="slot_duration" name="duration" type="number" min="5" max="120" value="15" required><label for="break_minutes">Break between slots (minutes)</label><input id="break_minutes" name="break_minutes" type="number" min="0" max="60" value="0" required><p class="field-help">Available only for a session without slots. At most 100 slots are generated.</p><button class="button">Generate the session’s slots</button></form></section>
<?php endif;?>
<section class="panel" id="assign"><h2>Assign an applicant</h2><form method="post" action="<?= e(p_url()) ?>"><?php p_csrf();p_hidden('action','appointment_save');p_hidden('appointment_id',0);?><label for="assign_application">Casting application</label><select id="assign_application" name="application_id" required><option value="">Choose application</option><?php foreach($view['applications'] as $app):?><option value="<?= (int)$app['id'] ?>"><?= e($app['full_name'].' · '.$app['title'].' · '.$app['reference']) ?></option><?php endforeach;?></select><label for="assign_slot">Available future slot</label><select id="assign_slot" name="slot_id" required><option value="">Choose slot</option><?php foreach($view['free_slots'] as $slot):?><option value="<?= (int)$slot['id'] ?>"><?= e($slot['title'].' · '.p_time($slot['starts_at'],$slot['display_zone'])) ?></option><?php endforeach;?></select><label for="assign_round">Audition round</label><select id="assign_round" name="round"><option value="initial">Initial audition</option><option value="callback">Callback</option></select><label for="assign_callback">Callback request (callback round only)</label><select id="assign_callback" name="callback_id"><option value="0">None</option><?php foreach($view['callbacks'] as $callback):if(!in_array($callback['state'],['requested','arranged'],true)){continue;}?><option value="<?= (int)$callback['id'] ?>">#<?= (int)$callback['id'] ?> · <?= e($callback['full_name'].' · '.$callback['reference']) ?></option><?php endforeach;?></select><label for="assign_note">Private booking note</label><textarea id="assign_note" name="private_note" rows="3" maxlength="4000"></textarea><button class="button">Assign slot and queue invitation</button></form></section>
<section class="panel" id="notices"><h2>Notices waiting for delivery</h2><p>Each send handles one message. If a send is interrupted, refresh after one minute before retrying. Retrying a failed invitation replaces its previous link. Provider acceptance is not proof of inbox delivery.</p><?php if(!$view['notices']):?><p>No pending notices.</p><?php endif;?><?php foreach($view['notices'] as $notice):?><form method="post" action="<?= e(p_url()) ?>"><?php p_csrf();p_hidden('action','notice_send');p_hidden('notice_id',$notice['id']);?><p><?= e($notice['full_name'].' · '.$notice['reference'].' · '.$notice['kind'].' · '.$notice['state']) ?> · Attempts <?= (int)$notice['attempts'] ?></p><button class="button">Send notice #<?= (int)$notice['id'] ?></button></form><?php endforeach;?></section>
<section class="panel" id="bookings"><h2>Bookings and attendance</h2><?php foreach($view['bookings'] as $booking):$bid=(int)$booking['id'];?><article class="booking" id="booking-<?= $bid ?>"><h3><?= e($booking['full_name']) ?> · #<?= $bid ?></h3><p><?= e($booking['reference'].' · '.$booking['title'].' · '.p_time($booking['starts_at'],$booking['display_zone'])) ?></p><p>Status: <?= e($booking['state']) ?> · Attendance: <?= e($booking['attendance']) ?> · Round: <?= e($booking['round']) ?></p><p><?= nl2br(e($booking['private_note'])) ?></p><div class="pager"><a class="text-link" href="<?= e(p_url('casting','auditions',['booking'=>$bid]).'#booking-'.$bid) ?>">Manage booking</a><a class="text-link" href="<?= e(p_url('casting','auditions',['application'=>$booking['application_id']])) ?>">Private history</a><a class="text-link" href="<?= e(p_url('casting','evaluations',['application'=>$booking['application_id']])) ?>">Evaluate applicant</a></div>
<?php if($view['managed_booking']===$bid):?><details open><summary>Reschedule or issue a fresh invitation</summary><form method="post" action="<?= e(p_url()) ?>"><?php p_csrf();p_hidden('action','appointment_save');p_hidden('appointment_id',$bid);p_hidden('application_id',$booking['application_id']);p_hidden('version',$booking['version']);p_hidden('round',$booking['round']);p_hidden('callback_id',$booking['callback_id']??0);?><label for="move_<?= $bid ?>">Target slot</label><select id="move_<?= $bid ?>" name="slot_id" required><option value="<?= (int)$booking['slot_id'] ?>">Current slot — fresh invitation if still future and available</option><?php foreach($view['free_slots'] as $slot):?><option value="<?= (int)$slot['id'] ?>"><?= e($slot['title'].' · '.p_time($slot['starts_at'],$slot['display_zone'])) ?></option><?php endforeach;?></select><label for="move_note_<?= $bid ?>">Private reason / note</label><textarea id="move_note_<?= $bid ?>" name="private_note" maxlength="4000" rows="3"></textarea><p class="field-help">This revokes older links, resets the response to invited and queues an updated invitation.</p><button class="button">Save new invitation</button></form></details>
<?php if(in_array($booking['state'],['invited','confirmed'],true)):?><details><summary>Record attendance</summary><form method="post" action="<?= e(p_url()) ?>"><?php p_csrf();p_hidden('action','attendance');p_hidden('appointment_id',$bid);?><label for="attendance_<?= $bid ?>">Attendance</label><select id="attendance_<?= $bid ?>" name="attendance"><?php foreach(['pending','present','absent'] as $attendance):?><option<?= $booking['attendance']===$attendance?' selected':'' ?>><?= e($attendance) ?></option><?php endforeach;?></select><label for="attendance_note_<?= $bid ?>">Private attendance note</label><textarea id="attendance_note_<?= $bid ?>" name="private_note" maxlength="4000" rows="3"></textarea><button class="button">Save attendance</button></form></details><form method="post" action="<?= e(p_url()) ?>"><?php p_csrf();p_hidden('action','appointment_cancel');p_hidden('appointment_id',$bid);p_hidden('version',$booking['version']);?><label for="cancel_note_<?= $bid ?>">Private cancellation reason</label><input id="cancel_note_<?= $bid ?>" name="private_note" maxlength="4000"><button class="sign-out">Cancel booking #<?= $bid ?></button></form><?php endif;?><?php endif;?></article><?php endforeach;?><div class="pager"><?php if($view['booking_page']>1):?><a href="<?= e(p_url('casting','auditions',['booking_page'=>$view['booking_page']-1]+($view['application']?['application'=>$view['application']['id']]:[]))) ?>">← Previous bookings</a><?php endif;?><?php if($view['more_bookings']):?><a href="<?= e(p_url('casting','auditions',['booking_page'=>$view['booking_page']+1]+($view['application']?['application'=>$view['application']['id']]:[]))) ?>">Next bookings →</a><?php endif;?></div></section>
<section class="panel" id="callbacks"><h2>Callback records</h2><form method="post" action="<?= e(p_url()) ?>"><?php p_csrf();p_hidden('action','callback_save');p_hidden('callback_id',0);p_hidden('callback_state','requested');?><label for="callback_application">Application for callback</label><select id="callback_application" name="application_id" required><option value="">Choose application</option><?php foreach($view['applications'] as $app):?><option value="<?= (int)$app['id'] ?>"><?= e($app['full_name'].' · '.$app['reference']) ?></option><?php endforeach;?></select><label for="callback_note">Private callback note</label><textarea id="callback_note" name="private_note" maxlength="4000" rows="3"></textarea><button class="button">Record callback request</button></form><?php foreach($view['callbacks'] as $callback):$cid=(int)$callback['id'];?><details><summary>#<?= $cid ?> · <?= e($callback['full_name'].' · '.$callback['state']) ?></summary><form method="post" action="<?= e(p_url()) ?>"><?php p_csrf();p_hidden('action','callback_save');p_hidden('callback_id',$cid);p_hidden('application_id',$callback['application_id']);?><label for="callback_state_<?= $cid ?>">Callback state</label><select id="callback_state_<?= $cid ?>" name="callback_state"><?php foreach(['requested','arranged','completed','closed'] as $state):?><option<?= $callback['state']===$state?' selected':'' ?>><?= e($state) ?></option><?php endforeach;?></select><label for="callback_note_<?= $cid ?>">Private callback note</label><textarea id="callback_note_<?= $cid ?>" name="private_note" rows="3" maxlength="4000"><?= e($callback['private_note']) ?></textarea><button class="button">Update callback record</button></form></details><?php endforeach;?></section>
<?php if($view['application']):?><section class="panel"><h2>Private audition history — <?= e($view['application']['reference']) ?></h2><?php foreach($view['events'] as $event):?><article><h3><?= e($event['action']) ?></h3><p><?= e($event['created_at'].' UTC · '.$event['actor_name']) ?></p><p><?= nl2br(e($event['private_note'])) ?></p><?php $past=json_decode($event['snapshot_json'],true);if(isset($past['starts_at'])):?><details><summary>Appointment details at this event</summary><?php $details=$past;require __DIR__.'/audition-details.php';?></details><?php endif;?></article><?php endforeach;?></section><?php endif;?>
